:root {
  color-scheme: light;
  font-family: Arial, sans-serif;
  color: #202d39;
  background: #f3f6f7;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(ellipse at 50% -30%, #e3f3ed 0, transparent 54%), #f3f6f7;
}

.shell { width: min(100% - 40px, 760px); margin: 0 auto; padding: 76px 0 96px; }
.page-header { margin-bottom: 38px; }
.eyebrow { color: #638575; font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 10px; font: 800 42px/1.15 Arial, sans-serif; letter-spacing: -.04em; }
.intro { margin: 0; color: #78858b; font-size: 15px; }
.create-form, .projects-section, .detail-card { border: 1px solid #e5eaeb; border-radius: 14px; background: #fff; box-shadow: 0 8px 24px #263b3c0a; }
.create-form { padding: 23px 24px 20px; }
label { display: block; margin-bottom: 9px; color: #4e5d63; font-size: 13px; font-weight: 600; }
.form-row { display: flex; gap: 10px; }
input { min-width: 0; flex: 1; height: 44px; padding: 0 13px; border: 1px solid #dce3e4; border-radius: 7px; color: inherit; font: inherit; outline: none; }
input::placeholder { color: #a0abad; }
input:focus { border-color: #448b70; box-shadow: 0 0 0 3px #448b7019; }
button { cursor: pointer; border: 0; border-radius: 7px; font: 600 13px Arial, sans-serif; }
.form-row button { padding: 0 17px; color: #fff; background: #286e54; box-shadow: 0 2px 4px #174d3822; }
.form-row button:hover { background: #205d46; }
.form-alert { margin: 10px 0 0; color: #b23838; font-size: 13px; }
.projects-section { margin-top: 25px; padding: 23px 24px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; }
h2 { margin: 0; font: 700 16px Arial, sans-serif; }
.count { color: #8a9699; font-size: 12px; }
.project-list { display: grid; gap: 9px; }
.project-row { display: flex; align-items: center; justify-content: space-between; min-height: 58px; padding: 9px 11px 9px 15px; border: 1px solid #edf0f0; border-radius: 8px; }
.project-name { overflow-wrap: anywhere; font-size: 14px; font-weight: 600; }
.open-button { padding: 9px 12px; color: #276e54; background: #edf6f1; }
.open-button:hover { background: #e1f0e8; }
.empty-state { margin: 8px 0 2px; padding: 22px 10px; color: #8a9699; text-align: center; font-size: 13px; }
.back-button { margin: 0 0 22px; padding: 8px 0; color: #36785e; background: transparent; font-size: 14px; }
.back-button:hover { color: #205d46; }
.detail-card { min-height: 190px; padding: 31px; }
.detail-card h1 { margin-top: 12px; }
[hidden] { display: none !important; }

@media (max-width: 560px) {
  .shell { width: min(100% - 28px, 760px); padding-top: 45px; }
  h1 { font-size: 35px; }
  .create-form, .projects-section { padding-right: 17px; padding-left: 17px; }
  .form-row { flex-direction: column; }
  .form-row button { height: 43px; }
}

